121	  "include": [{"zone": "z1"}, {"zone": "z2"}, {"zone": "z3"}],
122	  "exclude": [{"env": "temp"}],
123	  "clusters": [
124	    {"id": "c-d", "tags": {"zone": "z3"}},
125	    {"id": "x2", "tags": {"env": "temp"}},
126	    {"id": "c-b", "tags": {"zone": "z1"}},
127	    {"id": "x1", "tags": {"env": "dev"}},
128	    {"id": "off", "disabled": true},
129	    {"id": "c-e", "tags": {"zone": "z2"}},
130	    {"id": "c-a", "tags": {"zone": "z1"}},
131	    {"id": "c-c", "tags": {"zone": "z2"}}
132	  ]
133	}`
134		code, stdout, stderr := runCLI(t, "plan", writePlanDoc(t, doc))
135		if code != 0 {
136			t.Fatalf("expected exit 0, got %d; stderr=%q", code, stderr)
137		}
138		if stderr != "" {
139			t.Fatalf("expected empty stderr on success, got %q", stderr)
140		}
141	
142		p := decodeCLIPlan(t, stdout)
143		if p.App.Name != "payments" || p.App.Revision != "2026.10.0-r3" ||
144			p.App.Image != "registry.example.net/payments:2026.10.0-r3" {
145			t.Fatalf("app info not echoed from input: %+v", p.App)
146		}
147	
148		// Sorted selection is c-a,c-b (z1), c-c,c-e (z2), c-d (z3). Batch 1 takes
149		// the smallest IDs that fit: c-a(z1), c-c(z2), c-d(z3); c-b and c-e are
150		// deferred by domain conflicts and form batch 2.
151		domains := map[string]string{
152			"c-a": "z1", "c-b": "z1",
153			"c-c": "z2", "c-e": "z2",
154			"c-d": "z3",
155		}
156		assertSpreadBatches(t, p,
157			[][]string{{"c-a", "c-c", "c-d"}, {"c-b", "c-e"}},
158			domains, 3)
